// few are not:
//
//   - the theme is global process state, applied through theme.ApplyTheme;
//   - the secret backend decides which credentials.Storage the context holds,
//     which no view can rebuild itself into.
//
// The configuration view is deliberately kept rather than rebuilt: it is on
// screen, holds the cursor, and edits the very config object being handed back.
func (a *App) handleConfigSaved(msg configuration.ConfigSavedMsg) (tea.Model, tea.Cmd) {
	a.config = msg.Config
	// Cheap and idempotent, so no flag: every view is rebuilt below anyway.
	theme.SetGaugeGlyph(msg.Config.App.GaugeGlyph)

	if msg.ThemeChanged {
		a.applyThemeNow(msg.Config.App.Theme)
	}
	if msg.BackendChanged {
		a.resolveSecretBackend()
	}
	if msg.EngineChanged {
		a.resolveContainerEngine()
	}
	if msg.ForgeChanged {
		a.closeForgeSession()
	}

	// Every view except this one is dropped so it is rebuilt against the saved
	// config on next use. Keeping the configuration view is what stops a save
	// from throwing away the cursor after every keystroke.
	current := a.views[command.ViewConfiguration]
	a.views = make(map[command.ViewType]Screen)
	if current != nil {
		a.setView(command.ViewConfiguration, current)
	}
	a.createView(a.currentView)
	motionCmd := a.applyMotion(msg.Config)

	return a, tea.Batch(a.requestResize(), a.syncProxyPortCmd(), a.redetectIfToolsMoved(msg.EngineChanged), motionCmd)
}

// applyThemeNow switches the palette in place.
//
// It does not save: the configuration view already did, and writing twice would
// make the view's own config object and the file disagree about who is
// authoritative. That double write is what the `:theme` command did — it is
// gone, and this replaced it.
func (a *App) applyThemeNow(name string) {
	t, err := theme.LoadTheme(name)
	if err != nil {
		log.Printf("ERROR [app] load theme %q: %v", name, err)
		return
	}
	theme.ApplyTheme(t)
	theme.CurrentThemeName = name
}

}

// wantsBlink reports whether the view on screen has a row that blinks.
func (a *App) wantsBlink() bool {
	view, ok := a.views[a.currentView].(BlinkingView)
	return ok && view.WantsBlink()
}

// applyMotion points the animation at the motion a config asks for. It is
// called wherever the router takes a new config (context switch, every save);
// the constructor sets the field directly because it has no Cmd to return.
func (a *App) applyMotion(cfg *config.Config) tea.Cmd {
	return a.setMotionStatic(cfg.App.StaticMotion())
}

// setMotionStatic pins the blink phase on and stops blink-only chains. The view
// on screen is handed the pinned frame at once, otherwise it would keep an off
// phase until the next tick that may never come.
func (a *App) setMotionStatic(on bool) tea.Cmd {
	a.motionStatic = on
	if !on {
		return nil
	}
	a.anim.blinkOn = true
	return a.sendFrameTo(a.currentView)
}
