// declared — themes from a directory, views from the command parser; configPath
// because it names the context's file, which the config itself does not carry.
// forgeType and v name the tab and its words. The tab is titled after the
// platform the context targets, not after the section key: `forge:` is what the
// file says, and no user calls it that.
//
// contextName is the name of the context being edited; the config does not
// carry it, which is the same reason configPath is passed.
func sections(themes, views []string, configPath, contextName, forgeType string, v forge.Vocabulary, mcp MCPFacts) []section {
	return []section{
		{Title: "app", Fields: slices.Concat(
			group("Appearance", theme.IconDashboard,
				cycle("Theme", func(c *config.Config) *string { return &c.App.Theme }, themes,
					"Applied as you cycle it"),
				cycle("Default view", func(c *config.Config) *string { return &c.App.DefaultView }, views,
					"The view DevDesk opens on"),
				cycle("Gauge glyph", func(c *config.Config) *string { return &c.App.GaugeGlyph },
					config.GaugeGlyphs(), "block fills with a solid █, which some terminals draw double-width"),
				cycleWithDefault(motionLabel, func(c *config.Config) *string { return &c.App.Motion },
					config.Motions(), config.DefaultMotion,
					"static keeps a running row's dot steady — no blinking, no periodic redraw"),
			),
			group("Paths", theme.IconDirectory,
				pathField("Workspaces dir", func(c *config.Config) *string { return &c.App.WorkspacesDir },
					"Root the workspaces view browses", filebrowser.PickDir),
				// Where the keystrokes land. It is the one path the user cannot
				// change from here, so it is shown rather than edited — and it
				// belongs beside the other two, not alone in the header.
				static("Config file", configPath, "Written as you edit; there is no save step"),
				pathField("Log file", func(c *config.Config) *string { return &c.App.LogFile }, "", filebrowser.PickFile),
				// Last of the group: it qualifies the paths above it, and a

	return tabBar + "\n" + theme.EmptyLineBg(width) + "\n" + info
}

// status is the derived footer line (Rule 128): an app.motion the file holds
// outside its set is a standing fact, so it is a warning-level Status on the
// app tab rather than a message that would expire; otherwise the focused
// field's hint.
func (m Model) status() sharedcomponents.Status {
	if m.activeTab >= 0 && m.activeTab < len(m.sections) && m.sections[m.activeTab].Title == "app" &&
		!m.config.App.MotionValid() {
		return sharedcomponents.Status{
			Text: fmt.Sprintf("%s %q is not %s or %s — rows keep blinking",
				motionLabel, m.config.App.Motion, config.MotionBlink, config.MotionStatic),
			Level: sharedcomponents.LevelWarning,
		}
	}
	return sharedcomponents.Status{Text: m.hint(m.current())}
}

// GetShortcuts lists only what is not self-evident (Rules 130, 137, 138).

